const updaterUrl = "https://cdn.jsdelivr.net/gh/deepsleep-claw/SleepTavernHome@script-updater-v1.1.0/dist/%E5%85%AC%E5%85%B1%E6%A8%A1%E5%9D%97/%E8%84%9A%E6%9C%AC%E6%9B%B4%E6%96%B0%E5%99%A8/index.js";
const config = {
  "pluginId": "dream-card-agent",
  "pluginName": "梦境创客",
  "repository": "deepsleep-claw/SleepTavernHome",
  "manifestUrl": "https://raw.githubusercontent.com/deepsleep-claw/SleepTavernHome/main/manifest.json",
  "cdnBaseUrl": "https://cdn.jsdelivr.net/gh",
  "channel": "stable",
  "tagPrefix": "dream-card-agent-v",
  "updaterApiMajor": 1,
  "fallback": {
    "version": "0.2.4",
    "tag": "dream-card-agent-v0.2.4",
    "entry": "dist/酒馆助手/梦境创客/index.js",
    "url": "https://cdn.jsdelivr.net/gh/deepsleep-claw/SleepTavernHome@dream-card-agent-v0.2.4/dist/%E9%85%92%E9%A6%86%E5%8A%A9%E6%89%8B/%E6%A2%A6%E5%A2%83%E5%88%9B%E5%AE%A2/index.js",
    "updaterApiMajor": 1
  }
};
const source = getVariables({ type: 'script', script_id: getScriptId() }).__updater?.source;
globalThis.__thCdnSource = source;
const transport = (function createCdnRuntime(preference = 'auto', importRemote = url => import(/* webpackIgnore: true */ url)) {
  const origins = {
    jsdmirror: 'https://cdn.jsdmirror.com',
    jsdelivr: 'https://cdn.jsdelivr.net',
  };
  const source = preference === 'jsdelivr' || preference === 'jsdmirror' ? preference : 'auto';
  const order = source === 'jsdelivr' ? ['jsdelivr', 'jsdmirror'] : ['jsdmirror', 'jsdelivr'];
  const describeError = error => (error instanceof Error ? error.message : String(error));

  /** @param {string} url */
  function urls(url) {
    const parsed = new URL(url);
    if (!['cdn.jsdelivr.net', 'testingcf.jsdelivr.net', 'cdn.jsdmirror.com'].includes(parsed.hostname)) return [url];
    return order.map(id => `${origins[id]}${parsed.pathname}${parsed.search}${parsed.hash}`);
  }

  /** @param {string} url @param {RequestInit} [init] */
  async function fetchText(url, init = {}) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10_000);
    try {
      const response = await fetch(url, { ...init, signal: controller.signal });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return { text: await response.text(), contentType: response.headers.get('content-type') ?? '' };
    } finally {
      clearTimeout(timeout);
    }
  }

  /** @param {string} url @param {(module: any) => void} [validate] */
  async function importModule(url, validate = () => {}) {
    const errors = [];
    for (const candidate of urls(url)) {
      try {
        // 预取可取消并复用 HTTP 缓存；模块按顺序导入，避免重复执行。
        const response = await fetchText(candidate);
        if (!/(?:javascript|ecmascript)/iu.test(response.contentType)) throw new Error('响应不是 JavaScript 模块');
        const module = await importRemote(candidate);
        validate(module);
        return { module, url: candidate };
      } catch (error) {
        errors.push(`${new URL(candidate).hostname}: ${describeError(error)}`);
      }
    }
    throw new Error(`模块加载失败：${errors.join('；')}`);
  }

  /** @param {string} url @param {RequestInit} [init] */
  async function fetchResource(url, init = {}) {
    const errors = [];
    for (const candidate of urls(url)) {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 10_000);
      try {
        const response = await fetch(candidate, { ...init, signal: controller.signal });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const bytes = await response.arrayBuffer();
        return new Response(bytes, { status: response.status, headers: response.headers });
      } catch (error) {
        errors.push(`${new URL(candidate).hostname}: ${describeError(error)}`);
      } finally {
        clearTimeout(timeout);
      }
    }
    throw new Error(`资源加载失败：${errors.join('；')}`);
  }

  /** @param {HTMLLinkElement} link @param {string} url */
  function stylesheet(link, url) {
    const candidates = urls(url);
    let index = 0;
    link.addEventListener('error', () => {
      if (index + 1 < candidates.length) link.href = candidates[++index];
    });
    link.href = candidates[0];
  }

  return { source, urls, fetchText, fetchResource, importModule, stylesheet };
})(source);
const describeError = error => error instanceof Error && error.message ? error.message : String(error || '未知错误');

try {
  const loaded = await transport.importModule(updaterUrl, updater => {
    if (updater.UPDATER_API_MAJOR !== 1) {
      throw new Error(`更新器 API 不兼容：需要 v1，实际为 v${updater.UPDATER_API_MAJOR ?? '未知'}`);
    }
    if (updater.UPDATER_VERSION !== "1.1.0") {
      throw new Error(`更新器版本不匹配：需要 1.1.0，实际为 ${updater.UPDATER_VERSION ?? '未知'}`);
    }
    if (typeof updater.bootPlugin !== 'function') {
      throw new Error('更新器没有导出 bootPlugin()');
    }
  });
  await loaded.module.bootPlugin(config);
} catch (error) {
  console.error(`[${config.pluginName}] 启动失败。`, error);
  if (typeof toastr !== 'undefined') {
    toastr.error(`启动失败：${describeError(error)}`, config.pluginName);
  }
}
